1: ﻿<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>GAMEROAD Browser R29 Partner Selection Freeze</title>
2: <style>
3: :root{--bg:#07110f;--panel:#0a201b;--panel2:#12352c;--ink:#f5fff9;--muted:#a6c6bc;--line:rgba(197,246,228,.28);--a:#a0efd5;--b:#ffd27e;--c:#ff8d79;--shadow:0 18px 55px rgba(0,0,0,.34);--safe:clamp(12px,1.1vw,18px)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#040b0a;color:var(--ink);font-family:"Noto Sans JP","Yu Gothic",system-ui,sans-serif}body{position:fixed;inset:0}.app{width:100vw;height:100dvh;position:relative;overflow:hidden;background:radial-gradient(circle at 20% 18%,#16392f 0,transparent 32%),linear-gradient(135deg,#05110e,#0a1e19 60%,#040c0a)}button,input,select{font:inherit;color:inherit}button{cursor:pointer}.top{position:absolute;left:0;right:0;top:0;height:58px;padding:10px 18px;display:flex;align-items:center;justify-content:space-between;z-index:50;background:linear-gradient(180deg,rgba(4,13,11,.94),rgba(4,13,11,.24),transparent)}.brand{font-weight:1000;letter-spacing:.16em}.topRight{display:flex;gap:8px;align-items:center}.pill{border:1px solid var(--line);padding:7px 10px;background:rgba(5,20,16,.76);font-size:11px;font-weight:900}.screen{position:absolute;inset:0;display:none}.screen.active{display:block}.k{font-size:10px;letter-spacing:.16em;color:var(--a);font-weight:1000}.h{margin:4px 0;font-size:clamp(36px,5vw,82px);line-height:.94;font-weight:1000}.sub{font-size:12px;color:var(--muted);line-height:1.6}.btn{min-height:44px;min-width:44px;border:1px solid var(--line);background:#102c26;padding:0 14px;font-weight:900}.btn.primary{border-color:var(--a);background:#17483b}.btn.warn{border-color:rgba(255,141,121,.7)}.btn:disabled{opacity:.38;cursor:not-allowed}.back{position:absolute;left:auto;right:180px;top:8px;z-index:60}.toast{position:absolute;left:50%;bottom:18px;transform:translateX(-50%) translateY(30px);opacity:0;pointer-events:none;z-index:100;background:#edfdf6;color:#082018;padding:10px 16px;font-weight:900;transition:.18s}.toast.on{opacity:1;transform:translateX(-50%) translateY(0)}
4: /* HOME: world/character dominant, commands secondary. */
5: .homeScene{position:absolute;left:0;top:0;bottom:0;width:70%;overflow:hidden;background:linear-gradient(128deg,rgba(15,56,45,.72),rgba(6,18,16,.28))}.homeScene:after{content:"";position:absolute;inset:auto 0 0;height:40%;background:repeating-linear-gradient(105deg,rgba(38,95,73,.4) 0 24px,rgba(5,20,16,.02) 24px 48px);clip-path:polygon(0 48%,15% 21%,31% 49%,53% 4%,72% 36%,100% 10%,100% 100%,0 100%)}.heroRuntime{position:absolute;left:3%;top:7%;bottom:3%;width:43%;z-index:2;display:flex;align-items:flex-end;justify-content:center;overflow:hidden}.grtc-root,.grtc-facing,.grtc-primary-motion,.grtc-secondary-motion{width:100%;height:100%;display:flex;align-items:flex-end;justify-content:center}.grtc-primary-motion,.grtc-secondary-motion{transform-origin:50% 74%;will-change:transform}.grtc-image{height:92%;width:auto;max-width:100%;max-height:100%;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 22px 22px rgba(0,0,0,.35))}.grtc-source-blocked{position:relative;display:grid;place-items:center;min-height:120px}.grtc-source-blocked .grtc-facing{display:none}.grtc-source-blocked:after{content:attr(data-character-name);display:grid;place-items:center;width:min(62%,260px);aspect-ratio:3/4;border:1px solid var(--line);background:linear-gradient(145deg,rgba(160,239,213,.08),rgba(5,20,16,.62));font-size:clamp(16px,2.2vw,32px);font-weight:1000;letter-spacing:.06em;white-space:nowrap;padding:0 12px;color:rgba(245,255,249,.82);box-shadow:var(--shadow)}.heroFallback{font-weight:1000;font-size:clamp(60px,10vw,160px);opacity:.18;align-self:center}.homeCopy{position:absolute;left:7%;top:18%;width:48%;z-index:3;pointer-events:none}.homeCopy.withChar{left:47%;width:23%;top:18%}.homeRail{position:absolute;right:2%;top:11%;width:31%;bottom:9%;display:flex;flex-direction:column;justify-content:center;gap:7px;z-index:5}.homeCmd{position:relative;min-height:54px;text-align:left;padding:11px 18px 11px 24px;border:1px solid var(--line);background:rgba(7,26,21,.88);font-weight:1000;clip-path:polygon(5% 0,100% 0,96% 100%,0 100%);transform:translateX(10px)}.homeCmd.main{min-height:106px;font-size:26px;background:linear-gradient(90deg,#19473b,rgba(8,27,22,.92));border-color:var(--a);transform:translateX(-10px)}.homeCmd small{display:block;color:var(--muted);font-size:9px;margin-top:4px}.homeFoot{position:absolute;left:34%;bottom:4%;z-index:7;font-size:11px;color:var(--muted);letter-spacing:.08em}
